function validate([s, queries]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 3 || !query.every(Number.isInteger)) return 'Each query is [left, right, k] with whole numbers.';
    const [left, right, k] = query;
    if (left < 0 || left > right || right >= s.length) return 'Each query needs 0 <= left <= right < s.length.';
    if (k < 0 || k > s.length) return 'Each k is between 0 and s.length.';
  }
  return null;
}

