function canMakePaliQueries(s, queries) {
  const prefix = new Array(s.length + 1).fill(0);
  for (let i = 0; i < s.length; i++) {
    const bit = 1 << (s.charCodeAt(i) - 97);
    prefix[i + 1] = prefix[i] ^ bit;
  }

  const answer = [];
  for (const [left, right, k] of queries) {
    let odd = prefix[right + 1] ^ prefix[left];
    let oddCount = 0;
    while (odd !== 0) {
      odd &= odd - 1;
      oddCount++;
    }
    answer.push(Math.floor(oddCount / 2) <= k);
  }
  return answer;
}

