function canMakePaliQueries(s, queries) {
  return queries.map(([left, right, k]) => {
    const counts = {};
    for (const ch of s.slice(left, right + 1)) counts[ch] = (counts[ch] || 0) + 1;
    const odds = Object.values(counts).filter(c => c % 2 === 1).length;
    // Each change can pair up two letters with odd counts.
    let changes = 0;
    let remaining = odds;
    while (remaining > 1) { remaining -= 2; changes++; }
    return changes <= k;
  });
}

