function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const alphabet = large ? 26 : int(1, 6);
  const n = large ? 8000 : int(1, 10);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + int(0, alphabet - 1));
  const q = large ? 2000 : int(1, 6);
  const queries = [];
  for (let i = 0; i < q; i++) {
    let left = int(0, n - 1);
    let right = int(0, n - 1);
    if (left > right) [left, right] = [right, left];
    const k = rand() < 0.1 ? int(0, n) : int(0, Math.min(n, large ? 14 : 4));
    queries.push([left, right, k]);
  }
  return [s, queries];
}
